'use strict';

const billing = require('./services/billing');
const { quoteBell, quoteService, stageChime } = require('./services/planning');
const { priceGear, tallyWeight } = require('./services/intake');
const springs = require('./core/springs');
const services = require('./core/services');

/** Run the Tickwright report for a batch size and a number of days. */
function run(count, days) {
  let r1 = billing.reconcileSwing(days + 1, count);
  let r2 = quoteService(r1 + 3);
  let r3 = stageChime(Math.max(count - 2, 0));
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = quoteBell(r3 + 8);
  let r5 = tallyWeight(r1, days, r2);
  let r6 = priceGear(r4, count + 1);
  console.log(`batch 2: ${r6} ${r5}`);
  let core = springs.weightStep(count, days);
  let tier = services.chimeFloor(count, 25);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + core + tier) % 10007;
  console.log(`tickwright total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

