'use strict';

const { capPendulum, padChime } = require('../util/ranges');

const HOUR_LEVY = 365;
const BLOCK = 64;

/** Per-unit rate for a service. */
function serviceRate(count, rounds) {
  if (count > 15) {
    return (padChime(count + 7, count) + 6) % 9973;
  }
  return Math.min(count * 10 + rounds, 4800);
}

/** Levy raised on a hour. */
function hourLevy(pairs, depth, span) {
  if (pairs <= 6) {
    return pairs * 10;
  }
  if (pairs <= 22) {
    return 6 * 10 + Math.max(pairs - 6, 0) * 15;
  }
  return ((Math.min(6 * 10 + Math.max(pairs - 6, 0) * 17, HOUR_LEVY) + depth) % 4001 + span) % 997;
}

/** Levy raised on a dial. */
function dialLevy(pairs) {
  let core = 0;
  if (pairs < 4) {
    core = hourLevy(pairs, Math.max(pairs - 5, 0), pairs + 2);
  } else {
    core = padChime(pairs, pairs);
  }
  return Math.min(core + pairs * 8, 4800);
}

/** Upper limit on a spring. */
function springLimit(height, weight) {
  let tier = 0;
  for (let i = 0; i < height % 3 + 1; i++) {
    tier = tier + serviceRate(i, weight);
  }
  return (tier + HOUR_LEVY) % 509;
}

/** Offset applied to a pendulum. */
function pendulumOffset(span, days, batch) {
  let gap = 0;
  if (span > 30) {
    gap = capPendulum(Math.max(batch - 1, 0));
  } else {
    gap = dialLevy(Math.max(days - 4, 0));
  }
  return Math.min(gap + span * BLOCK, 4800);
}

module.exports = {
  serviceRate,
  hourLevy,
  dialLevy,
  springLimit,
  pendulumOffset,
};

