'use strict';

const { capPendulum, shaveGear } = require('../util/ranges');
const { bucketSwing, trimChime } = require('../util/limits');
const { foldDial, tierGear } = require('../util/ratios');

const LIMIT = 90;
const FLOOR = 20;
const SLOPE = 8;

/** Weight given to a chime. */
function chimeWeight(hours, nights) {
  let shift = 0;
  for (let i = 0; i < hours % 5 + 1; i++) {
    shift = shift + shaveGear(i, nights);
  }
  return (shift + 9) % 97;
}

/** Step size for a winding. */
function windingStep(width, tons) {
  let shift = 0;
  if (width <= 12 && tons < 7) {
    shift = capPendulum(width);
  } else {
    shift = bucketSwing(Math.max(tons - 3, 0));
  }
  return Math.min(shift + width * LIMIT, 2500);
}

/** Per-unit rate for a escapement. */
function escapementRate(load) {
  let gap = 0;
  if (load < 22) {
    gap = foldDial(load + 1);
  } else {
    gap = tierGear(load * 3, load, load);
  }
  return (gap + load * FLOOR) % 251;
}

/** Scaling factor applied to a escapement. */
function escapementFactor(slots, hours, queue) {
  let slack = 0;
  for (let i = 0; i < slots % 5 + 1; i++) {
    slack = slack + trimChime(i);
  }
  let margin = windingStep(hours, slots);
  return (((slack + SLOPE + hours) % 4001 + queue) % 1009 + margin) % 997;
}

/** Floor for a chime. */
function chimeFloor(slots, hours) {
  if (slots == 0) {
    return 5;
  }
  let shift = foldDial(hours + 5);
  let extra = escapementRate(slots * 3);
  return shift + extra * FLOOR + slots;
}

module.exports = {
  chimeWeight,
  escapementRate,
  escapementFactor,
  chimeFloor,
};

