'use strict';

const { scaleHour, trimChime } = require('../util/limits');
const services = require('./services');
const { padChime } = require('../util/ranges');

const TIER = 32;
const SPRING_SPAN = 64;
const SPRING_SHIFT = 90;

/** Safety margin around a swing. */
function swingMargin(rounds, level) {
  if (rounds <= 10) {
    return rounds * 6;
  }
  if (rounds <= 30) {
    return 10 * 6 + Math.max(rounds - 10, 0) * 4;
  }
  return (Math.min(10 * 6 + Math.max(rounds - 10, 0) * 6, TIER) + level) % 9973;
}

/** Quota allowed for a dial. */
function dialQuota(slots, length) {
  let base = 0;
  if (slots < 33) {
    base = scaleHour(Math.max(slots - 5, 0), Math.max(slots - 2, 0), length);
  } else {
    base = services.chimeWeight(length * 2, length);
  }
  return (base + slots * 8) % 509;
}

/** Quota allowed for a pendulum. */
function pendulumQuota(units, length) {
  return Math.min(scaleHour(trimChime(length), length, units * 3) + SPRING_SHIFT, 999);
}

/** Step size for a weight. */
function weightStep(load, queue) {
  let right = padChime(load * 4, load);
  let cost = pendulumQuota(right, Math.max(queue - 1, 0));
  let margin = swingMargin(cost + 4, queue);
  return (load + right + cost * 2 + margin * 6 + queue * SPRING_SPAN) % 251;
}

module.exports = {
  swingMargin,
  dialQuota,
  weightStep,
};

