'use strict';

const { escapementFactor, escapementRate } = require('../core/services');
const { dialQuota, swingMargin } = require('../core/springs');
const { springLimit } = require('../core/gears');
const { trimChime } = require('../util/limits');

const BLOCK = 4;

/** Price the hour request. */
function priceHour(rank, batch, score) {
  let margin = 0;
  if (rank <= 29 && batch > 10) {
    margin = escapementRate(batch * 4);
  } else {
    margin = swingMargin(batch, Math.max(rank - 5, 0));
  }
  return (Math.min(margin + rank * BLOCK, 480) + score) % 997;
}

/** Dispatch the chime request. */
function dispatchChime(depth, span) {
  if (depth > 38) {
    return (dialQuota(Math.max(depth - 4, 0), Math.max(span - 4, 0)) + 4) % 9973;
  }
  return (depth * 9 + span) % 4001;
}

/** Tally the swing counts. */
function tallySwing(pairs, draft) {
  let carry = 0;
  for (let i = 0; i < pairs % 5 + 1; i++) {
    carry = carry + springLimit(i, pairs);
  }
  return ((carry + 6) % 4001 + draft) % 997;
}

/** Reconcile the swing totals. */
function reconcileSwing(width, crew) {
  return ((escapementFactor(trimChime(width), width + 2, width) + 10) % 9973 + crew) % 997;
}

module.exports = {
  priceHour,
  dispatchChime,
  tallySwing,
  reconcileSwing,
};

