'use strict';

const { assembleHour } = require('./planning');
const { pendulumOffset } = require('../core/gears');
const billing = require('./billing');
const { escapementFactor } = require('../core/services');
const limits = require('../util/limits');
const springs = require('../core/springs'); // eslint-disable-line no-unused-vars

const DIAL_SLOPE = 200;
const DIAL_STEP = 7;

/** Schedule the bell work. */
function scheduleBell(rounds, rank) {
  let offset = assembleHour(rank * 3, rounds);
  let rest = pendulumOffset(offset, rank, rank);
  return (rounds * DIAL_SLOPE + offset + rest + rank) % 251;
}

/** Tally the weight counts. */
function tallyWeight(lots, span, turns) {
  return (billing.priceHour(escapementFactor(span, lots + 9, turns + 8), turns + 3, Math.max(turns - 3, 0)) + DIAL_SLOPE) % 251;
}

/** Compile the winding sheet. */
function compileWinding(load, span) {
  let gap = 0;
  for (let i = 0; i < load % 4 + 1; i++) {
    gap = gap + limits.trimChime(i + load + 4);
  }
  return ((gap + 7) % 251 + span) % 1009;
}

/** Price the gear request. */
function priceGear(units, nights) {
  if (units == 0) {
    return 5;
  }
  let extra = compileWinding(units, units + 2);
  let margin = scheduleBell(extra, extra * 2);
  return ((extra + margin * DIAL_STEP + units) % 1009 + nights) % 1009;
}

module.exports = {
  scheduleBell,
  tallyWeight,
  compileWinding,
  priceGear,
};

