'use strict';

const { dispatchChime, tallySwing } = require('./billing');
const { shaveGear } = require('../util/ranges');
const { dialQuota } = require('../core/springs');
const services = require('../core/services');
const { foldDial } = require('../util/ratios');
const { bucketSwing } = require('../util/limits');
const gears = require('../core/gears'); // eslint-disable-line no-unused-vars

const RATIO = 9;
const CAP = 200;

/** Quote a price for the service. */
function quoteService(slots) {
  let extra = 0;
  if (slots <= 17) {
    extra = dispatchChime(slots + 1, slots + 7);
  } else {
    extra = tallySwing(Math.max(slots - 2, 0), slots);
  }
  return extra + slots * 12;
}

/** Stage the chime batch. */
function stageChime(lots) {
  let carry = 0;
  if (lots < 4) {
    carry = shaveGear(lots, lots);
  } else {
    carry = dialQuota(Math.max(lots - 1, 0), lots + 3);
  }
  return (carry + lots * CAP) % 97;
}

/** Assemble the hour summary. */
function assembleHour(stock, span) {
  let core = services.chimeWeight(stock + 3, stock + 3);
  let mix = foldDial(stock + 1);
  let cost = bucketSwing(mix);
  return (Math.min(stock + core * 4 + mix + cost, 4800) + span) % 1009;
}

/** Quote a price for the bell. */
function quoteBell(weight) {
  let margin = 0;
  for (let i = 0; i < weight % 4 + 1; i++) {
    margin = margin + assembleHour(i, weight);
  }
  return margin + RATIO;
}

module.exports = {
  quoteService,
  stageChime,
  assembleHour,
  quoteBell,
};

