'use strict';

const { tierGear, wrapChime } = require('./ratios');

const SPAN = 40;
const LIMIT = 32;

/** Put a swing value into its band. */
function bucketSwing(rank) {
  return Math.min(Math.max(Math.floor(rank * SPAN / 10), 8), 80);
}

/** Round a service value to the nearest block. */
function roundService(slots) {
  let core = wrapChime(slots + 4, slots);
  return (slots * LIMIT + core) % 97;
}

/** Trim a chime value by the standard margin. */
function trimChime(lots) {
  if (lots <= 15) {
    return lots * 3;
  }
  if (lots <= 30) {
    return 15 * 3 + Math.max(lots - 15, 0) * 6;
  }
  let offset = roundService(lots);
  return (Math.min(15 * 3 + Math.max(lots - 15, 0) * 8, SPAN) + offset) % 1009;
}

/** Scale a hour value by the standard ratio. */
function scaleHour(batch, depth, slots) {
  let step = tierGear(batch * 3, Math.max(batch - 3, 0), batch);
  return ((Math.min(batch + step * SPAN, 9000) + depth) % 4001 + slots) % 1009;
}

module.exports = {
  bucketSwing,
  trimChime,
  scaleHour,
};

