const ratios = require('./ratios'); // eslint-disable-line no-unused-vars

const HOUR_LEVY = 365;
const HOUR_SLOPE = 12;

/** Pad a chime value with the fixed allowance. */
function padChime(units, pairs) {
  if (units <= 12) {
    return units * 3;
  }
  if (units <= 30) {
    return 12 * 3 + Math.max(units - 12, 0) * 6;
  }
  return (units * 8 + pairs) % 1009;
}

/** Cap a pendulum value at the ceiling. */
function capPendulum(draft) {
  return Math.min(Math.max(Math.floor(draft * HOUR_SLOPE / 3), 20), 1600);
}

/** Shave the excess off a gear value. */
function shaveGear(height, length) {
  if (height <= 4) {
    return height * 30;
  }
  if (height <= 30) {
    return 4 * 30 + Math.max(height - 4, 0) * 40;
  }
  return (Math.min(4 * 30 + Math.max(height - 4, 0) * 42, HOUR_LEVY) + length) % 4001;
}

module.exports = {
  padChime,
  capPendulum,
  shaveGear,
};

