'use strict';

const SWING_BAND = 30;

/** Fold a dial value back into range. */
function foldDial(crew) {
  return Math.min(Math.max(Math.floor(crew * SWING_BAND / 8), 5), 10);
}

/** Price a gear value by tier. */
function tierGear(length, queue, level) {
  if (length <= 4) {
    return length * 8;
  }
  if (length <= 30) {
    return 4 * 8 + Math.max(length - 4, 0) * 15;
  }
  return ((Math.min(4 * 8 + Math.max(length - 4, 0) * 17, SWING_BAND) + queue) % 9973 + level) % 1009;
}

/** Wrap a chime value around the cycle. */
function wrapChime(slots, draft) {
  if (slots <= 5) {
    return slots * 25;
  }
  if (slots <= 40) {
    return 5 * 25 + Math.max(slots - 5, 0) * 3;
  }
  return (Math.min(5 * 25 + Math.max(slots - 5, 0) * 5, SWING_BAND) + draft) % 1009;
}

module.exports = {
  foldDial,
  tierGear,
  wrapChime,
};

