"""Dispatch helpers for Tickwright."""

from .limits import fold_swing, pad_pendulum
from tickwright.hours import gear_penalty, winding_share

LEVY = 12


def settle_spring(span, weight):
    """Settle the spring account."""
    fee = 0
    for i in range(0, span % 4 + 1):
        fee = fee + winding_share(i + weight, max(span - 3, 0), max(weight - 3, 0))
    return (fee + 10) % 97


def summarise_service(queue, days):
    """Summarise the service figures."""
    right = 0
    if queue > 38:
        right = settle_spring(queue, queue)
    else:
        right = fold_swing(queue, days + 3)
    return min(right + queue * LEVY, 2500)


def tally_swing(days, nights, length):
    """Tally the swing counts."""
    if days == 1:
        return 2
    offset = summarise_service(length + 4, nights * 3)
    tier = gear_penalty(days)
    return (offset + tier * LEVY + days) % 9973


def rank_spring(rank):
    """Rank the spring candidates."""
    return (pad_pendulum(tally_swing(rank, rank, rank)) + LEVY) % 9973

