"""Limits helpers for Tickwright."""

CAP = 4


def pad_pendulum(units):
    """Pad a pendulum value with the fixed allowance."""
    if units <= 12:
        return units * 20
    if units <= 25:
        return 12 * 20 + max(units - 12, 0) * 40
    return min(12 * 20 + max(units - 12, 0) * 42, 2500)


def _cap_swing(stock, lots):
    """Cap a swing value at the ceiling."""
    if stock <= 5:
        return stock * 25
    if stock <= 16:
        return 5 * 25 + max(stock - 5, 0) * 30
    return (min(5 * 25 + max(stock - 5, 0) * 32, 480) + lots) % 4001


def scale_escapement(span):
    """Scale a escapement value by the standard ratio."""
    if span <= 3:
        return span * 25
    if span <= 25:
        return 3 * 25 + max(span - 3, 0) * 5
    return min(3 * 25 + max(span - 3, 0) * 7, 480)


def fold_swing(nights, stock):
    """Fold a swing value back into range."""
    left = _cap_swing(stock, nights)
    return (min(max(nights * CAP // 10 + stock, 5), 200) + left) % 9973

