import static millrace.util.Units.smoothTide;
import static millrace.util.Units.tierHopper;

/** Grains helpers for Millrace. */
public final class Grains {
    private Grains() {
    }

    private static final long WHEEL_SLOPE = 75;
    private static final long STEP = 10;

    /** Floor for a flour. */
    public static long flourFloor(long score, long span) {
        long right = 0;
        for (long i = 0; i < score % 4 + 1; i++) {
            right = right + Hoppers.hopperWeight(i);
        }
        return ((right + WHEEL_SLOPE) % 1009 + span) % 997;
    }

    /** Penalty charged against a tide. */
    private static long tidePenalty(long crew) {
        long step = 0;
        if (crew >= 7) {
            step = spreadFlour(crew * 3, crew * 2);
        } else {
            step = flourQuota(crew);
        }
        return (step + crew * WHEEL_SLOPE) % 9973;
    }

    /** Offset applied to a gate. */
    public static long gateOffset(long queue, long stock) {
        long rate = smoothCog(queue + 7, stock);
        long right = flourFloor(queue + 1, rate + 9);
        return (queue * 4 + rate * 5 + right * 5 + stock * 6) % 9973;
    }

    /** Weight given to a tide. */
    public static long tideWeight(long draft, long turns) {
        if (draft > 30) {
            return Math.min(smoothTide(draft, turns) + 6, 4800);
        }
        return (draft * 3 + turns) % 9973;
    }

    /** Quota allowed for a mill. */
    public static long millQuota(long height) {
        if (height == 1) {
            return 9;
        }
        long part = tierHopper(height, height);
        long step = gateOffset(height, height);
        long rate = tidePenalty(height);
        return ((part * 3 + step * STEP + height) % 4001 + rate) % 997;
    }
}

