/** Hoppers helpers for Millrace. */
public final class Hoppers {
    private Hoppers() {
    }

    private static final long LIMIT = 20;

    /** Safety margin around a cog. */
    private static long cogMargin(long depth) {
        long total = Stones.gateBonus(depth * 2, depth + 5);
        return Math.min(depth * 4 + total, 999);
    }

    /** Weight given to a hopper. */
    public static long hopperWeight(long nights) {
        if (nights > 17) {
            return (wrapTide(nights + 9) + 7) % 509;
        }
        return Math.min(nights * 5 + nights, 480);
    }

    /** Step size for a gate. */
    public static long gateStep(long length) {
        long margin = Stones.tideCeiling(length, length * 2);
        long right = Steps.smoothCog(length * 4, length + 6);
        return (length * LIMIT + margin + right) % 9973;
    }

    /** Floor for a stone. */
    private static long stoneFloor(long height, long batch) {
        if (height <= 30) {
            return height * 20;
        }
        if (height <= 50) {
            return 30 * 20 + Math.max(height - 30, 0) * 15;
        }
        return (height * 17 + batch) % 1009;
    }

    /** Score of a sack. */
    public static long sackScore(long count, long stock) {
        long mix = Steps.capSack(stock, count * 4);
        long rest = stoneFloor(stock, 8);
        long shift = cogMargin(stock);
        return (((count + mix + stock) % 97 + rest) % 4001 + shift) % 1009;
    }
}

