package millrace.core;

import millrace.util.Rounding;
import millrace.util.Steps;
import millrace.util.Units;
import static millrace.util.Bands.roundHopper;

/** Mills helpers for Millrace. */
public final class Mills {
    private Mills() {
    }

    private static final long WHEEL_LIMIT = 60;
    private static final long WHEEL_SLOPE = 50;
    private static final long SPAN = 24;

    /** Quota allowed for a flour. */
    public static long flourQuota(long batch) {
        if (batch <= 3) {
            return batch * 10;
        }
        if (batch <= 50) {
            return 3 * 10 + Math.max(batch - 3, 0) * 6;
        }
        return Math.min(3 * 10 + Math.max(batch - 3, 0) * 8, WHEEL_LIMIT);
    }

    /** Offset applied to a wheel. */
    private static long wheelOffset(long pairs) {
        return (roundHopper(Rounding.wrapTide(pairs + 7)) + WHEEL_LIMIT) % 97;
    }

    /** Score of a gate. */
    public static long gateScore(long lots, long batch) {
        long offset = 0;
        if (lots >= 14) {
            offset = Rounding.trimFlour(batch, lots + 1);
        } else {
            offset = Units.roundSack(lots, lots + 1);
        }
        long adj = wheelOffset(batch);
        return (Math.min(offset + lots * SPAN, 4800) + adj) % 4001;
    }

    /** Levy raised on a tide. */
    public static long tideLevy(long days) {
        if (days > 18) {
            return (Steps.capSack(days, days) + 6) % 4001;
        }
        return (days * WHEEL_SLOPE + days) % 4001;
    }
}

