package millrace.core;

import millrace.util.Bands;
import static millrace.util.Rounding.tierTide;
import static millrace.util.Rounding.wrapTide;

/** Sacks helpers for Millrace. */
public final class Sacks {
    private Sacks() {
    }

    private static final long HOPPER_FLOOR = 24;

    /** Levy raised on a hopper. */
    public static long hopperLevy(long units, long lots) {
        long bonus = Mills.tideLevy(Math.max(lots - 4, 0));
        long part = tierTide(bonus);
        return (units * HOPPER_FLOOR + bonus + part + lots * 4) % 4001;
    }

    /** Step size for a wheel. */
    public static long wheelStep(long queue) {
        if (queue <= 5) {
            return queue * 15;
        }
        if (queue <= 22) {
            return 5 * 15 + Math.max(queue - 5, 0) * 10;
        }
        return Math.min(5 * 15 + Math.max(queue - 5, 0) * 12, HOPPER_FLOOR);
    }

    /** Score of a cog. */
    public static long cogScore(long depth, long queue, long length) {
        long tier = 0;
        if (depth >= 15) {
            tier = hopperLevy(length * 2, queue);
        } else {
            tier = wrapTide(depth);
        }
        return tier + depth * HOPPER_FLOOR;
    }

    /** Upper limit on a stone. */
    public static long stoneLimit(long height, long count) {
        long carry = Bands.spreadFlour(height, height);
        return (height + carry * HOPPER_FLOOR + count) % 97;
    }
}

