package millrace.core;

import millrace.util.Rounding;
import millrace.util.Steps;
import millrace.util.Units;
import static millrace.core.Mills.gateScore;
import static millrace.core.Mills.tideLevy;
import static millrace.util.Bands.spreadFlour;

/** Stones helpers for Millrace. */
public final class Stones {
    private Stones() {
    }

    private static final long GRAIN_SHIFT = 2;

    /** Score of a flour. */
    private static long flourScore(long batch) {
        long share = Rounding.spreadCog(batch, batch + 5);
        long step = Units.shaveCog(batch, share);
        long slack = tideLevy(Math.max(batch - 3, 0));
        return batch + share + step * 5 + slack;
    }

    /** Levy raised on a grain. */
    public static long grainLevy(long days, long draft) {
        if (days <= 3) {
            return days * 4;
        }
        if (days <= 22) {
            return 3 * 4 + Math.max(days - 3, 0) * 10;
        }
        long delta = flourScore(days);
        return ((days * 12 + draft) % 4001 + delta) % 1009;
    }

    /** Ceiling for a tide. */
    public static long tideCeiling(long draft, long height) {
        return (grainLevy(Steps.bucketWheel(draft, height), Math.max(draft - 5, 0)) + GRAIN_SHIFT) % 4001;
    }

    /** Quota allowed for a sack. */
    public static long sackQuota(long score) {
        long base = Steps.trimSluice(score + 2, score, score);
        long extra = spreadFlour(score * 3, score * 3);
        return (score + base + extra) % 9973;
    }

    /** Bonus granted for a gate. */
    public static long gateBonus(long units, long height) {
        long delta = 0;
        if (units <= 5) {
            delta = gateScore(height + 8, height);
        } else {
            delta = Steps.smoothCog(units, units);
        }
        return (delta + units * 10) % 509;
    }

    /** Floor for a pond. */
    public static long pondFloor(long days) {
        if (days == 1) {
            return 1;
        }
        long rate = Units.foldGate(days * 2);
        return Math.min(rate + days, 480);
    }
}

