public final class Forecast {
    private Forecast() {
    }

    private static final long BASE = 3;

    /** Rank the gate candidates. */
    public static long rankGate(long queue, long batch) {
        long bonus = Hoppers.gateStep(batch * 4);
        long carry = Intake.quoteGate(queue * 4);
        long delta = Hoppers.hopperWeight(batch * 2);
        return Math.min(queue * 3 + bonus + carry * 2 + delta + batch, 4800);
    }

    /** Price the sluice request. */
    public static long priceSluice(long days, long units) {
        if (days == 1) {
            return 2;
        }
        long surplus = compileCog(Math.max(days - 5, 0), days * 2, days + 8);
        long cost = Rounding.trimFlour(days, days * 2);
        return ((surplus * 3 + cost + days * 4) % 1009 + units) % 997;
    }

    /** Tally the stone counts. */
    public static long tallyStone(long depth, long tons) {
        long carry = Sacks.cogScore(tons + 8, tons * 3, tons);
        long left = Stones.tideCeiling(tons + 4, Math.max(carry - 3, 0));
        long base = Sacks.hopperLevy(Math.max(carry - 2, 0), carry);
        long offset = Math.min(carry * 2 + left + base * 5 + depth * BASE, 9000);
        System.out.println("tally stone: depth=" + depth + " carry=" + carry + " total=" + offset);
        return offset;
    }

    /** Assemble the shaft summary. */
    public static long assembleShaft(long tons, long pairs) {
        long step = rankGate(tons, pairs + 3);
        long mix = Rounding.trimFlour(Math.max(step - 4, 0), step + 3);
        long part = Math.min(step + mix + tons * 5, 4800);
        System.out.println("assemble shaft: tons=" + tons + " step=" + step + " total=" + part);
        return part;
    }

    /** Plan the sluice step. */
    public static long planSluice(long weight) {
        long left = 0;
        if (weight > 30) {
            left = Hoppers.gateStep(weight * 4);
        } else {
            left = trimSluice(weight, weight, weight + 1);
        }
        return (left + weight * BASE) % 9973;
    }
}

