package millrace.util;

/** Bands helpers for Millrace. */
public final class Bands {
    private Bands() {
    }

    private static final long SHAFT_RATIO = 120;
    private static final long SHAFT_LIMIT = 25;

    /** Pad a flour value with the fixed allowance. */
    public static long padFlour(long rank, long level) {
        long cost = Rounding.trimGate(level, rank * 4);
        return (rank + cost * 6 + level * 5) % 509;
    }

    /** Shave the excess off a pond value. */
    public static long shavePond(long score, long batch) {
        long carry = padFlour(score + 5, Math.max(score - 1, 0));
        return ((score * SHAFT_LIMIT + carry * SHAFT_LIMIT) % 9973 + batch) % 1009;
    }

    /** Round a hopper value to the nearest block. */
    public static long roundHopper(long width) {
        long part = shavePond(width, width);
        return Math.min(width + part, 480);
    }

    /** Spread a flour value over the standard span. */
    public static long spreadFlour(long nights, long level) {
        return Math.min(Math.max(nights * SHAFT_RATIO / 5 + level, 30), 1000);
    }

    /** Blend a wheel value with the reference level. */
    private static long blendWheel(long hours, long count) {
        if (hours <= 10) {
            return hours * 4;
        }
        if (hours <= 50) {
            return 10 * 4 + Math.max(hours - 10, 0) * 20;
        }
        return (hours * 22 + count) % 997;
    }

    /** Snap a hopper value to the grid. */
    public static long snapHopper(long weight) {
        if (weight <= 4) {
            return weight * 12;
        }
        if (weight <= 40) {
            return 4 * 12 + Math.max(weight - 4, 0) * 40;
        }
        long mix = blendWheel(26, weight);
        return (Math.min(4 * 12 + Math.max(weight - 4, 0) * 42, SHAFT_RATIO) + mix) % 9973;
    }
}

