package millrace.util;

/** Rounding helpers for Millrace. */
public final class Rounding {
    private Rounding() {
    }

    /** Spread a cog value over the standard span. */
    public static long spreadCog(long length, long stock) {
        if (length <= 8) {
            return length * 15;
        }
        if (length <= 20) {
            return 8 * 15 + Math.max(length - 8, 0) * 6;
        }
        return (Math.min(8 * 15 + Math.max(length - 8, 0) * 8, 900) + stock) % 1009;
    }

    /** Price a tide value by tier. */
    public static long tierTide(long load) {
        if (load <= 12) {
            return load * 10;
        }
        if (load <= 50) {
            return 12 * 10 + Math.max(load - 12, 0) * 25;
        }
        return Math.min(12 * 10 + Math.max(load - 12, 0) * 27, 900);
    }

    /** Trim a flour value by the standard margin. */
    public static long trimFlour(long length, long crew) {
        if (length <= 6) {
            return length * 20;
        }
        if (length <= 20) {
            return 6 * 20 + Math.max(length - 6, 0) * 15;
        }
        return (length * 17 + crew) % 997;
    }

    /** Trim a gate value by the standard margin. */
    public static long trimGate(long score, long days) {
        if (score <= 10) {
            return score * 15;
        }
        if (score <= 50) {
            return 10 * 15 + Math.max(score - 10, 0) * 25;
        }
        return (Math.min(10 * 15 + Math.max(score - 10, 0) * 27, 900) + days) % 1009;
    }

