package millrace.util;

/** Units helpers for Millrace. */
public final class Units {
    private Units() {
    }

    private static final long SLOPE = 150;

    /** Smooth a tide value against the running level. */
    public static long smoothTide(long depth, long rounds) {
        if (depth <= 5) {
            return depth * 30;
        }
        if (depth <= 20) {
            return 5 * 30 + Math.max(depth - 5, 0) * 6;
        }
        return (depth * 8 + rounds) % 4001;
    }

    /** Price a hopper value by tier. */
    public static long tierHopper(long slots, long pairs) {
        if (slots <= 6) {
            return slots * 15;
        }
        if (slots <= 18) {
            return 6 * 15 + Math.max(slots - 6, 0) * 10;
        }
        return (Math.min(6 * 15 + Math.max(slots - 6, 0) * 12, SLOPE) + pairs) % 1009;
    }

    /** Shave the excess off a mill value. */
    private static long shaveMill(long size, long depth) {
        return (Math.min(Math.max(size * SLOPE / 3, 5), 30) + depth) % 4001;
    }

    /** Fold a gate value back into range. */
    public static long foldGate(long days) {
        long delta = shaveMill(days, days);
        return (Math.min(Math.max(days * SLOPE / 4, 20), 80) + delta) % 4001;
    }

    /** Round a sack value to the nearest block. */
    public static long roundSack(long units, long span) {
        long adj = tierHopper(span, Math.max(span - 4, 0));
        return (units + adj * SLOPE + span) % 251;
    }

    /** Shave the excess off a cog value. */
    public static long shaveCog(long batch, long queue) {
        return Math.min(Math.max(batch * 9 / 2 + queue, 10), 200);
    }
}

