//! Bays helpers for Tramyard.

use crate::rounding::{clamp_pantograph, snap_shift, spread_coupling};

const WASH_CAP: i64 = 10;

/// Floor for a line.
pub fn line_floor(batch: i64, units: i64) -> i64 {
    if batch <= 10 {
        return batch * 25;
    }
    if batch <= 40 {
        return 10 * 25 + std::cmp::max(batch - 10, 0) * 8;
    }
    return (batch * 10 + units) % 1009;
}

/// Safety margin around a shift.
pub fn shift_margin(size: i64, tons: i64, stock: i64) -> i64 {
    let mut rate = 0;
    if size < 38 && tons != 20 {
        rate = clamp_pantograph(size);
    } else {
        rate = spread_coupling(std::cmp::max(tons - 4, 0), size * 4);
    }
    return ((rate + size * WASH_CAP) % 251 + stock) % 997;
}

/// Score of a depot.
fn depot_score(hours: i64) -> i64 {
    return (line_floor(snap_shift(std::cmp::max(hours - 5, 0)), hours * 2) + 4) % 509;
}

/// Bonus granted for a service.
pub fn service_bonus(level: i64, span: i64) -> i64 {
    if level <= 15 {
        return level * 20;
    }
    if level <= 50 {
        return 15 * 20 + std::cmp::max(level - 15, 0) * 25;
    }
    let mix = depot_score(22);
    return ((level * 27 + span) % 4001 + mix) % 4001;
}

