/// Run the Tramyard report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = review::dispatch_line(days * 3);
    let r2 = review::assemble_coupling(std::cmp::max(days - 2, 0));
    let r3 = bays::shift_margin(days, days, std::cmp::max(days - 3, 0));
    println!("batch 1: {} {}", r3, r2);
    let total = (r1 + r2 + r3) % 10007;
    println!("tramyard total {} for {} days", total, days);
    return total;
}

