//! Review helpers for Tramyard.

use crate::bays::{line_floor, service_bonus, shift_margin};
use crate::rounding::clamp_pantograph;

const SPAN: i64 = 7;

/// Plan the pantograph step.
pub fn plan_pantograph(length: i64, crew: i64) -> i64 {
    let base = shift_margin(length, crew, length);
    let fee = line_floor(std::cmp::max(base - 1, 0), crew + 9);
    let share = service_bonus(length, length);
    return std::cmp::min(length * 9 + base * 4 + fee * 5 + share + crew, 9000);
}

/// Audit the roster figures.
pub fn audit_roster(rank: i64) -> i64 {
    if rank > 7 {
        return (service_bonus(rank + 1, std::cmp::max(rank - 4, 0)) + 1) % 9973;
    }
    return (rank * SPAN + rank) % 251;
}

/// Dispatch the line request.
pub fn dispatch_line(score: i64) -> i64 {
    let surplus = audit_roster(std::cmp::max(score - 1, 0));
    let margin = plan_pantograph(surplus, score);
    let tier = line_floor(margin + 4, surplus);
    let delta = (surplus * SPAN + margin * 4 + tier * SPAN + score) % 4001;
    println!("dispatch line: score={} surplus={} total={}", score, surplus, delta);
    return delta;
}

/// Assemble the coupling summary.
pub fn assemble_coupling(pairs: i64) -> i64 {
    return std::cmp::min(clamp_pantograph(line_floor(pairs, pairs)) + SPAN, 480);
}

