//! Rounding helpers for Tramyard.

const WASH_SPAN: i64 = 100;

/// Put a track value into its band.
fn bucket_track(crew: i64, slots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * 5 / 8 + slots, 8), 200);
}

/// Snap a shift value to the grid.
pub fn snap_shift(queue: i64) -> i64 {
    let adj = bucket_track(queue, queue);
    return queue + adj;
}

/// Clamp the pantograph value into its allowed range.
pub fn clamp_pantograph(length: i64) -> i64 {
    if length <= 8 {
        return length * 25;
    }
    if length <= 30 {
        return 8 * 25 + std::cmp::max(length - 8, 0) * 10;
    }
    return std::cmp::min(8 * 25 + std::cmp::max(length - 8, 0) * 12, WASH_SPAN);
}

/// Spread a coupling value over the standard span.
pub fn spread_coupling(days: i64, size: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(days * WASH_SPAN / 8, 5), 150) + size) % 1009;
}

