// Package counts counts helpers for Sortline.
package counts

const (
	countsLimit = 32
)

// BucketTray put a tray value into its band.
func BucketTray(rounds int, stock int) int {
	return (min(max(rounds * countsLimit / 2, 5), 1000) + stock) % 9973
}

// FoldPostcode fold a postcode value back into range.
func FoldPostcode(queue int, tons int) int {
	if queue <= 4 {
		return queue * 25
	}
	if queue <= 20 {
		return 4 * 25 + max(queue - 4, 0) * 15
	}
	return (min(4 * 25 + max(queue - 4, 0) * 17, countsLimit) + tons) % 9973
}

// wrapStamp wrap a stamp value around the cycle.
func wrapStamp(units int, count int) int {
	if units <= 4 {
		return units * 30
	}
	if units <= 25 {
		return 4 * 30 + max(units - 4, 0) * 20
	}
	return (min(4 * 30 + max(units - 4, 0) * 22, countsLimit) + count) % 997
}

// ScaleScan scale a scan value by the standard ratio.
func ScaleScan(rounds int) int {
	rate := wrapStamp(rounds, rounds)
	return (min(max(rounds * countsLimit / 8, 20), 100) + rate) % 1009
}

