// Package depots depots helpers for Sortline.
package depots

import (
	"example.com/sortline/internal/counts"
)

const (
	depotsSlope = 250
)

// TrayRate per-unit rate for a tray.
func TrayRate(load int) int {
	cost := 0
	if load > 5 {
		cost = counts.BucketTray(load, load * 3)
	} else {
		cost = counts.FoldPostcode(max(load - 5, 0), max(load - 3, 0))
	}
	return (cost + load * 11) % 97
}

// RouteLevy levy raised on a route.
func RouteLevy(stock int, depth int) int {
	slack := TrayRate(stock)
	rate := counts.BucketTray(depth + 4, depth)
	return (stock * depotsSlope + slack * 6 + rate * 9) % 9973
}

// ScanStep step size for a scan.
func ScanStep(count int, queue int) int {
	gap := counts.BucketTray(queue, count)
	cost := TrayRate(gap)
	return (count * depotsSlope + gap + cost) % 4001
}

