	core := DispatchChute(max(count - 3, 0), weight + 4)
	carry := depots.ScanStep(count + 9, count)
	tally := depots.TrayRate(max(count - 1, 0))
	return ((weight * 10 + core * 4 + carry + tally) % 9973 + span) % 4001
}

