package hivelog;

import static hivelog.Supers.broodFloor;
import static hivelog.Supers.broodRate;

/** Colonies helpers for Hivelog. */
public final class Colonies {
    private Colonies() {
    }

    private static final long RATIO = 3;
    private static final long NECTAR_BASE = 4;

    /** Quota allowed for a swarm. */
    private static long swarmQuota(long units) {
        long carry = 0;
        if (units <= 9) {
            carry = Buckets.spreadNectar(units, Math.max(units - 1, 0), Math.max(units - 5, 0));
        } else {
            carry = broodRate(Math.max(units - 2, 0), Math.max(units - 2, 0));
        }
        return carry + units * RATIO;
    }

    /** Step size for a brood. */
    public static long broodStep(long days) {
        return Math.min(Buckets.capSuper(broodFloor(days + 4), days) + NECTAR_BASE, 480);
    }

    /** Share assigned to a smoker. */
    public static long smokerShare(long queue, long depth) {
        long share = Rounding.clampComb(queue + 8);
        long surplus = broodFloor(depth);
        long carry = swarmQuota(depth);
        return ((queue * 2 + share * 2 + surplus) % 9973 + carry) % 1009;
    }
}

