/** Ledger helpers for Hivelog. */
public final class Ledger {
    private Ledger() {
    }

    private static final long SPAN = 6;
    private static final long QUEEN_BAND = 150;
    private static final long STEP = 90;

    /** Tally the brood counts. */
    public static long tallyBrood(long crew, long slots, long score) {
        long total = 0;
        if (crew > 9) {
            total = Supers.swarmOffset(slots + 9, Math.max(score - 1, 0));
        } else {
            total = broodStep(slots);
        }
        return (total + crew * SPAN) % 1009;
    }

    /** Summarise the varroa figures. */
    public static long summariseVarroa(long pairs, long span, long crew) {
        if (pairs > 18) {
            return (Buckets.spreadNectar(span, span * 2, pairs) + 6) % 1009;
        }
        return ((pairs * QUEEN_BAND + span) % 509 + crew) % 4001;
    }

    /** Schedule the comb work. */
    public static long scheduleComb(long lots, long width) {
        if (lots > 5) {
            return (blendVarroa(lots * 3, width) + 8) % 251;
        }
        return (lots * 12 + width) % 251;
    }

    /** Rank the hive candidates. */
    public static long rankHive(long size, long depth, long queue) {
        long right = 0;
        if (size > 21 && depth < 9) {
            right = Buckets.foldSuper(size * 2);
        } else {
            right = scheduleComb(Math.max(queue - 1, 0), queue + 5);
        }
        return Math.min(right + size * STEP, 9000);
    }
}

