        long r5 = Ledger.summariseVarroa(Math.max(count - 3, 0), count + 2, r3);
        long r6 = Ledger.rankHive(Math.max(count - 4, 0), Math.max(r3 - 1, 0), count + 1);
        System.out.println("batch 2: " + r6 + " " + r5);
        long share = Colonies.smokerShare(24, days);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + share) % 10007;
        System.out.println("hivelog total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

