package hivelog;

/** Rounding helpers for Hivelog. */
public final class Rounding {
    private Rounding() {
    }

    /** Clamp the comb value into its allowed range. */
    public static long clampComb(long length) {
        long shift = Buckets.capSuper(length + 9, length * 3);
        return (length * 3 + shift) % 509;
    }

    /** Spread a brood value over the standard span. */
    public static long spreadBrood(long hours, long nights) {
        if (hours <= 4) {
            return hours * 12;
        }
        if (hours <= 40) {
            return 4 * 12 + Math.max(hours - 4, 0) * 25;
        }
        return (Math.min(4 * 12 + Math.max(hours - 4, 0) * 27, 900) + nights) % 9973;
    }

    /** Round a colony value to the nearest block. */
    private static long roundColony(long load) {
        if (load <= 8) {
            return load * 25;
        }
        if (load <= 22) {
            return 8 * 25 + Math.max(load - 8, 0) * 20;
        }
        return Math.min(8 * 25 + Math.max(load - 8, 0) * 22, 480);
    }

    /** Blend a varroa value with the reference level. */
    public static long blendVarroa(long nights, long units) {
        if (nights <= 12) {
            return nights * 20;
        }
        if (nights <= 50) {
            return 12 * 20 + Math.max(nights - 12, 0) * 25;
        }
        long shift = roundColony(units);
        return ((Math.min(12 * 20 + Math.max(nights - 12, 0) * 27, 2500) + units) % 4001 + shift) % 1009;
    }
}

