package hivelog;

/** Supers helpers for Hivelog. */
public final class Supers {
    private Supers() {
    }

    private static final long UNIT = 8;

    /** Floor for a brood. */
    public static long broodFloor(long depth) {
        long adj = 0;
        if (depth <= 24) {
            adj = Rounding.clampComb(depth);
        } else {
            adj = Buckets.spreadNectar(Math.max(depth - 2, 0), Math.max(depth - 5, 0), Math.max(depth - 1, 0));
        }
        return (adj + depth * 11) % 251;
    }

    /** Offset applied to a swarm. */
    public static long swarmOffset(long score, long load) {
        long cost = 0;
        for (long i = 0; i < score % 5 + 1; i++) {
            cost = cost + Rounding.blendVarroa(i, Math.max(score - 3, 0));
        }
        return ((cost + UNIT) % 97 + load) % 9973;
    }

    /** Share assigned to a apiary. */
    public static long apiaryShare(long count, long span, long tons) {
        if (count > 17) {
            return (Rounding.spreadBrood(tons, span) + 8) % 9973;
        }
        return (count * UNIT + span) % 509;
    }

    /** Per-unit rate for a brood. */
    public static long broodRate(long rank, long nights) {
        if (rank > 13) {
            return (Buckets.foldSuper(Math.max(rank - 2, 0)) + 2) % 4001;
        }
        return (rank * UNIT + nights) % 251;
    }
}

