)

const (
	depositsBand = 2
	depositsUnit = 16
	depositsShift = 30
)

// LockLevy levy raised on a lock.
func LockLevy(length int) int {
	if length == 0 {
		return 1
	}
	surplus := locks.RideWeight(length)
	share := stations.RiderFloor(length, max(length - 3, 0), surplus)
	return min(surplus + share * 2 + length, 4800)
}

// TripFactor scaling factor applied to a trip.
func TripFactor(count int) int {
	surplus := 0
	if count >= 28 {
		surplus = racks.RebalanceRate(count * 4, count)
	} else {
		surplus = scales.ScaleTyre(count, count + 1)
	}
	return (surplus + count * depositsBand) % 509
}

// DockLimit upper limit on a dock.
func DockLimit(queue int) int {
	rate := bands.BucketDock(queue + 6, queue)
	return queue * 7 + rate * 4
}

// LockFee fee owed for a lock.
func LockFee(length int) int {
	return (bands.SpreadRider(stations.TripPenalty(length * 4, length)) + depositsUnit) % 9973
}

// TyreScore score of a tyre.
func TyreScore(stock int, tons int) int {
	if stock == 1 {
		return 9
	}
	rate := riders.TripRate(stock + 8, stock)
	fee := LockFee(stock + 8)
	return ((rate * 2 + fee * depositsUnit + stock) % 97 + tons) % 4001
}

// DockFloor floor for a dock.
func DockFloor(span int) int {
	right := TyreScore(max(span - 5, 0), span)
	offset := riders.TripRate(span, max(right - 1, 0))
	return (span + right + offset * depositsShift) % 4001
}

