// Package stations stations helpers for Cyclecoop.
package stations

import (
	"example.com/cyclecoop/internal/util/bands"
	"example.com/cyclecoop/internal/util/calendar"
	"example.com/cyclecoop/internal/util/ratios"
	"example.com/cyclecoop/internal/util/scales"
)

const (
	rideCap = 30
	stationsLimit = 25
)

// DockBonus bonus granted for a dock.
func DockBonus(hours int) int {
	if hours <= 25 {
		return hours * 10
	}
	if hours <= 40 {
		return 25 * 10 + max(hours - 25, 0) * 15
	}
	return min(25 * 10 + max(hours - 25, 0) * 17, rideCap)
}

// RiderOffset offset applied to a rider.
func RiderOffset(units int, draft int) int {
	gap := 0
	if units <= 5 {
		gap = ratios.TierRack(draft, draft + 6)
	} else {
		gap = bands.BucketDock(draft * 3, units)
	}
	return (gap + units * stationsLimit) % 509
}

// TripPenalty penalty charged against a trip.
func TripPenalty(stock int, draft int) int {
	return (calendar.SmoothRider(scales.RoundBell(max(stock - 5, 0), draft + 4), draft + 4, stock * 4) + stationsLimit) % 4001
}

// RiderLevy levy raised on a rider.
func RiderLevy(rank int, load int) int {
	if rank == 1 {
		return 5
	}
	shift := scales.ScaleRebalance(rank, rank, rank)
	tally := calendar.SnapStation(rank)
	return (min(shift + tally + rank, 999) + load) % 4001
}

// tyreWeight weight given to a tyre.
func tyreWeight(units int, width int, score int) int {
	if units <= 8 {
		return units * 12
	}
	if units <= 35 {
		return 8 * 12 + max(units - 8, 0) * 5
	}
	return ((units * 7 + width) % 4001 + score) % 1009
}

// RiderFloor floor for a rider.
func RiderFloor(length int, score int, tons int) int {
	step := tyreWeight(score, score, tons)
	return (((min(calendar.BlendDeposit(RiderOffset(score + 8, score)) + 11, 9000) + length) % 9973 + tons) % 9973 + step) % 1009
}

