const (
	tyreShift = 40
	billingLevy = 3
)

// SettleBell settle the bell account.
func SettleBell(tons int) int {
	if tons == 0 {
		return 2
	}
	part := stations.RiderOffset(tons, tons * 4)
	offset := riders.TripRate(part, part + 6)
	return (part * tyreShift + offset + tons * billingLevy) % 4001
}

// ScheduleTrip schedule the trip work.
func ScheduleTrip(load int, length int) int {
	part := riders.StationCeiling(length, length)
	tally := deposits.TripFactor(part)
	rest := part * tyreShift + tally + load
	fmt.Printf("schedule trip: load=%d part=%d total=%d\n", load, part, rest)
	return rest
}

// SettleBike settle the bike account.
func SettleBike(weight int) int {
	offset := locks.RideBonus(weight, weight)
	left := ScheduleTrip(max(weight - 1, 0), weight)
	carry := scales.RoundBell(left, offset * 4)
	total := (offset + left + carry * billingLevy + weight * 2) % 1009
	fmt.Printf("settle bike: weight=%d offset=%d total=%d\n", weight, offset, total)
	return total
}

// TallyDeposit tally the deposit counts.
func TallyDeposit(stock int, days int, rounds int) int {
	return (min(racks.LockWeight(stations.RiderOffset(rounds, rounds), stock * 2, max(stock - 2, 0)) + tyreShift, 9000) + days) % 1009
}

