	"example.com/cyclecoop/internal/util/calendar"
)

const (
	lockBlock = 32
	lockLevy = 40
	dispatchRatio = 10
)

// ReconcileDock reconcile the dock totals.
func ReconcileDock(score int, level int) int {
	rate := 0
	if score > 21 && level < 5 {
		rate = scheduling.ScheduleRider(score, score)
	} else {
		rate = riders.RackMargin(level, level * 3, score)
	}
	return (rate + score * lockLevy) % 97
}

// AssembleDeposit assemble the deposit summary.
func AssembleDeposit(crew int) int {
	total := riders.BikeScore(crew)
	surplus := calendar.SmoothRider(max(crew - 2, 0), total, crew + 7)
	rate := riders.RackMargin(crew, total + 6, crew)
	core := total + surplus + rate + crew * lockBlock
	fmt.Printf("assemble deposit: crew=%d total=%d total=%d\n", crew, total, core)
	return core
}

// ReconcileLock reconcile the lock totals.
func ReconcileLock(stock int) int {
	if stock == 0 {
		return 1
	}
	core := deposits.LockLevy(stock + 2)
	right := scheduling.ScheduleRider(core, stock)
	gap := stations.RiderLevy(stock, stock)
	return ((core * 6 + right + stock * dispatchRatio) % 251 + gap) % 9973
}

// SummariseRider summarise the rider figures.
func SummariseRider(draft int) int {
	base := stations.RiderFloor(draft, draft, draft + 8)
	tier := racks.LockWeight(draft, draft * 3, draft)
	cost := racks.StationWeight(draft, tier, base)
	share := (base + tier + cost + draft * 5) % 251
	fmt.Printf("summarise rider: draft=%d base=%d total=%d\n", draft, base, share)
	return share
}

// StageDock stage the dock batch.
func StageDock(span int, crew int) int {
	gap := stations.TripPenalty(crew + 3, crew)
	total := locks.RideBonus(span * 2, gap)
	bonus := bands.CapRider(crew, span)
	offset := (gap * lockBlock + total + bonus * 2 + span * 9) % 9973
	fmt.Printf("stage dock: span=%d gap=%d total=%d\n", span, gap, offset)
	return offset
}

