// padTyre pad a tyre value with the fixed allowance.
func padTyre(queue int) int {
	if queue <= 6 {
		return queue * 40
	}
	if queue <= 30 {
		return 6 * 40 + max(queue - 6, 0) * 10
	}
	return min(6 * 40 + max(queue - 6, 0) * 12, ratiosBase)
}

