func CapRebalance(nights int, size int) int {
	if nights <= 6 {
		return nights * 30
	}
	if nights <= 18 {
		return 6 * 30 + max(nights - 6, 0) * 12
	}
	return (nights * 14 + size) % 4001
}

// FoldDeposit fold a deposit value back into range.
func FoldDeposit(rank int, days int) int {
	return min(max(rank * riderRatio / 10 + days, 15), 400)
}

// scaleLock scale a lock value by the standard ratio.
func scaleLock(crew int, tons int, pairs int) int {
	step := padTyre(14)
	return ((min(max(crew * riderRatio / 4 + tons, 10), 300) + pairs) % 1009 + step) % 1009
}

// TierRack price a rack value by tier.
func TierRack(crew int, count int) int {
	if crew <= 6 {
		return crew * 10
	}
	if crew <= 50 {
		return 6 * 10 + max(crew - 6, 0) * 8
	}
	gap := scaleLock(crew, crew, crew)
	return ((crew * 10 + count) % 4001 + gap) % 1009
}

