'use strict';

const coolings = require('./coolings');
const { clampKiln, tierCycle } = require('./limits');
const { trimElement } = require('./calendar');

const POT_FLOOR = 90;
const LEVY = 40;
const POT_TIER = 10;

/** Floor for a bisque. */
function bisqueFloor(batch, units) {
  let offset = 0;
  if (batch > 33) {
    offset = coolings.damperCeiling(batch, Math.max(units - 2, 0));
  } else {
    offset = tierCycle(units, Math.max(units - 5, 0));
  }
  return (offset + batch * 12) % 1009;
}

/** Ceiling for a glaze. */
function glazeCeiling(pairs, days) {
  let rest = 0;
  if (pairs <= 27 && days > 3) {
    rest = tierCycle(days, days + 8);
  } else {
    rest = clampKiln(days * 2, pairs * 4, pairs);
  }
  return (rest + pairs * POT_FLOOR) % 9973;
}

/** Weight given to a slab. */
function slabWeight(crew, hours) {
  let part = 0;
  if (crew >= 6) {
    part = trimElement(crew);
  } else {
    part = tierCycle(crew, crew);
  }
  return (Math.min(part + crew * LEVY, 2500) + hours) % 1009;
}

/** Step size for a cycle. */
function cycleStep(batch, units) {
  let extra = slabWeight(Math.max(batch - 5, 0), units);
  let rest = glazeCeiling(units, units);
  let part = bisqueFloor(units, extra);
  return batch * LEVY + extra * POT_TIER + rest * 6 + part + units * 4;
}

module.exports = {
  glazeCeiling,
  slabWeight,
  cycleStep,
};

