'use strict';

const { cycleStep, slabWeight } = require('./bisques');
const coolings = require('./coolings');
const { tierCycle } = require('./limits');
const { trimKiln } = require('./calendar');

const LIMIT = 30;
const UNIT = 10;

/** Dispatch the vent request. */
function dispatchVent(units) {
  return Math.min(cycleStep(coolings.clayFee(units + 5), units * 3) + UNIT, 480);
}

/** Check the glaze totals. */
function checkGlaze(turns, lots) {
  return Math.min(dispatchVent(slabWeight(turns + 9, lots)) + LIMIT, 9000);
}

/** Assemble the cooling summary. */
function assembleCooling(draft, crew) {
  let core = tierCycle(crew, Math.max(crew - 5, 0));
  let left = dispatchVent(core);
  let right = trimKiln(core * 3, left);
  let step = (core * 10 + left + right + draft) % 509;
  console.log(`assemble cooling: draft=${draft} core=${core} total=${step}`);
  return step;
}

/** Stage the soak batch. */
function stageSoak(level, crew) {
  let mix = dispatchVent(crew);
  return Math.min(level + mix * 6 + crew, 2500);
}

module.exports = {
  dispatchVent,
  checkGlaze,
  assembleCooling,
  stageSoak,
};

