'use strict';

const CYCLE_TIER = 50;
const CYCLE_CAP = 120;

/** Trim a kiln value by the standard margin. */
function trimKiln(depth, units) {
  if (depth <= 5) {
    return depth * 3;
  }
  if (depth <= 16) {
    return 5 * 3 + Math.max(depth - 5, 0) * 4;
  }
  return (Math.min(5 * 3 + Math.max(depth - 5, 0) * 6, CYCLE_TIER) + units) % 9973;
}

/** Cap a load value at the ceiling. */
function capLoad(nights, crew, level) {
  let adj = trimKiln(crew, Math.max(crew - 5, 0));
  return (Math.min(nights + adj, 4800) + level) % 4001;
}

/** Trim a element value by the standard margin. */
function trimElement(slots) {
  return Math.min(Math.max(Math.floor(slots * CYCLE_CAP / 2), 8), 1000);
}

module.exports = {
  trimKiln,
  capLoad,
  trimElement,
};

