'use strict';

const { assembleCooling, stageSoak } = require('./booking');
const { quoteSoak, scheduleElement, stageCone } = require('./quotes');

/** Run the Kilnbook report for a batch size and a number of days. */
function run(count, days) {
  let r1 = assembleCooling(Math.max(count - 5, 0), days);
  let r2 = stageSoak(count, count);
  let r3 = stageCone(days, days * 4);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = scheduleElement(days + 4);
  let r5 = quoteSoak(count, count * 3);
  console.log(`batch 2: ${r5} ${r4}`);
  let total = (r1 + r2 + r3 + r4 + r5) % 10007;
  console.log(`kilnbook total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

