'use strict';

const { clampKiln, tierCycle } = require('./limits');
const calendar = require('./calendar');

/** Safety margin around a batch. */
function batchMargin(nights, units) {
  let bonus = tierCycle(nights, units);
  let rate = calendar.capLoad(bonus, units + 8, nights);
  let tally = calendar.trimElement(nights);
  return (nights + bonus + rate * 5 + tally) % 251;
}

/** Ceiling for a damper. */
function damperCeiling(score, turns) {
  if (score <= 10) {
    return score * 12;
  }
  if (score <= 30) {
    return 10 * 12 + Math.max(score - 10, 0) * 15;
  }
  return (score * 17 + turns) % 997;
}

/** Fee owed for a clay. */
function clayFee(rank) {
  let extra = tierCycle(rank, rank + 9);
  let surplus = clampKiln(Math.max(rank - 1, 0), rank, rank);
  let delta = batchMargin(extra, extra + 5);
  return Math.min(rank * 3 + extra * 4 + surplus * 4 + delta, 999);
}

module.exports = {
  damperCeiling,
  clayFee,
};

