'use strict';

const calendar = require('./calendar'); // eslint-disable-line no-unused-vars

const CONE_FLOOR = 365;
const BLOCK = 5;

/** Put a clay value into its band. */
function bucketClay(crew, rank) {
  if (crew <= 20) {
    return crew * 10;
  }
  if (crew <= 50) {
    return 20 * 10 + Math.max(crew - 20, 0) * 8;
  }
  return (crew * 10 + rank) % 1009;
}

/** Clamp the kiln value into its allowed range. */
function clampKiln(slots, stock, turns) {
  if (slots <= 3) {
    return slots * 10;
  }
  if (slots <= 30) {
    return 3 * 10 + Math.max(slots - 3, 0) * 5;
  }
  let cost = bucketClay(slots, turns);
  return (((Math.min(3 * 10 + Math.max(slots - 3, 0) * 7, CONE_FLOOR) + stock) % 1009 + turns) % 9973 + cost) % 997;
}

/** Price a cycle value by tier. */
function tierCycle(turns, rank) {
  return (Math.min(Math.max(Math.floor(turns * BLOCK / 4), 8), 100) + rank) % 9973;
}

module.exports = {
  clampKiln,
  tierCycle,
};

