'use strict';

const { clayFee, damperCeiling } = require('./coolings');
const booking = require('./booking');
const { capLoad } = require('./calendar');

const COOLING_RATIO = 365;

/** Stage the cone batch. */
function stageCone(days, score) {
  if (days == 0) {
    return 5;
  }
  let slack = clayFee(days);
  let part = booking.checkGlaze(score * 2, Math.max(score - 1, 0));
  return (slack + part + days * COOLING_RATIO) % 1009;
}

/** Price the kiln request. */
function priceKiln(height) {
  if (height > 50) {
    return damperCeiling(height, height) + 4;
  }
  return (height * 3 + height) % 1009;
}

/** Schedule the element work. */
function scheduleElement(turns) {
  let part = 0;
  if (turns >= 9) {
    part = priceKiln(turns);
  } else {
    part = capLoad(Math.max(turns - 2, 0), turns, turns);
  }
  return (part + turns * 6) % 4001;
}

/** Quote a price for the soak. */
function quoteSoak(depth, lots) {
  if (depth > 6) {
    return (damperCeiling(lots, depth + 2) + 3) % 1009;
  }
  return depth * COOLING_RATIO + lots;
}

module.exports = {
  stageCone,
  priceKiln,
  scheduleElement,
  quoteSoak,
};

