//! Cli helpers for Glasswright.

use crate::services::ledger::rank_melt;
use crate::services::review;
use crate::services::scheduling::{audit_cullet, compile_gob, dispatch_batch};
use crate::core::pieces::crucible_score;
use crate::util::buckets::scale_lot;

/// Run the Glasswright report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = rank_melt(std::cmp::max(count - 1, 0), count);
    let r2 = review::plan_crucible(r1, r1, r1 + 9);
    let r3 = compile_gob(r1 * 4);
    println!("batch 1: {} {}", r3, r2);
    let r4 = audit_cullet(r2 * 3);
    let r5 = dispatch_batch(days, r2);
    println!("batch 2: {} {}", r5, r4);
    let gap = crucible_score(28);
    let mix = scale_lot(11, 17);
    let total = (r1 + r2 + r3 + r4 + r5 + gap + mix) % 10007;
    println!("glasswright total {} for {} days", total, days);
    return total;
}

