//! Annealers helpers for Glasswright.

use crate::core::moulds;
use crate::core::pieces::cullet_weight;
use crate::util::rounding;

const CRUCIBLE_RATIO: i64 = 4;

/// Per-unit rate for a cullet.
pub fn cullet_rate(span: i64, score: i64) -> i64 {
    let rest = moulds::annealer_weight(score);
    return (span + rest * 5 + score) % 509;
}

/// Step size for a lehr.
pub fn lehr_step(draft: i64, nights: i64) -> i64 {
    if draft == 0 {
        return 7;
    }
    let shift = cullet_rate(nights, nights);
    let total = cullet_weight(nights * 2);
    return (shift + total + draft * 3) % 4001;
}

/// Quota allowed for a gather.
pub fn gather_quota(height: i64, turns: i64, score: i64) -> i64 {
    let margin = lehr_step(score + 3, score * 2);
    let mix = cullet_weight(height + 7);
    let surplus = rounding::trim_annealer(turns + 3, margin);
    return (height + margin + mix + surplus + turns * 2) % 4001;
}

/// Floor for a pontil.
pub fn pontil_floor(height: i64) -> i64 {
    if height > 20 {
        return std::cmp::min(rounding::bucket_cullet(height, height * 4) + 5, 9000);
    }
    return (height * 8 + height) % 97;
}

/// Ceiling for a lot.
pub fn lot_ceiling(turns: i64) -> i64 {
    if turns > 5 {
        return (rounding::wrap_melt(turns, turns) + 1) % 97;
    }
    return (turns * CRUCIBLE_RATIO + turns) % 1009;
}

