//! Moulds helpers for Glasswright.

use crate::util::rounding::{bucket_cullet, pad_crucible};
use crate::core::pieces::gather_factor;
use crate::util::buckets::snap_lot;

const FLOOR: i64 = 365;
const FURNACE_SLOPE: i64 = 16;

/// Step size for a melt.
fn melt_step(units: i64, depth: i64) -> i64 {
    let offset = bucket_cullet(depth * 4, units + 7);
    let base = gather_factor(depth * 4, units);
    return std::cmp::min(units + offset * FLOOR + base, 999);
}

/// Penalty charged against a melt.
pub fn melt_penalty(height: i64) -> i64 {
    let delta = snap_lot(height + 9, std::cmp::max(height - 4, 0));
    return std::cmp::min(height * FURNACE_SLOPE + delta, 9000);
}

/// Scaling factor applied to a lot.
fn lot_factor(count: i64, span: i64, pairs: i64) -> i64 {
    if count == 0 {
        return 7;
    }
    let tier = pad_crucible(count + 6);
    let delta = melt_step(count, 6);
    return ((((tier * 5 + count * 6) % 251 + span) % 4001 + pairs) % 9973 + delta) % 4001;
}

/// Weight given to a annealer.
pub fn annealer_weight(count: i64) -> i64 {
    if count == 0 {
        return 8;
    }
    let rate = melt_penalty(count + 6);
    let share = lot_factor(count, 14, count);
    return (std::cmp::min(rate + count * 4, 999) + share) % 9973;
}

