//! Pieces helpers for Glasswright.

use crate::util::counts::cap_piece;
use crate::util::rounding::{shave_furnace, trim_annealer, wrap_melt};
use crate::util::buckets;

const TIER: i64 = 7;
const BATCH_FLOOR: i64 = 75;

/// Step size for a blow.
pub fn blow_step(hours: i64, queue: i64, slots: i64) -> i64 {
    let gap = cap_piece(std::cmp::max(hours - 3, 0), slots, slots);
    return (hours * 3 + gap + queue * 4) % 97;
}

/// Floor for a piece.
pub fn piece_floor(tons: i64, days: i64) -> i64 {
    if tons <= 10 {
        return tons * 4;
    }
    if tons <= 40 {
        return 10 * 4 + std::cmp::max(tons - 10, 0) * 15;
    }
    return (tons * 17 + days) % 4001;
}

/// Scaling factor applied to a gather.
pub fn gather_factor(level: i64, load: i64) -> i64 {
    let cost = shave_furnace(load);
    let offset = blow_step(std::cmp::max(load - 4, 0), std::cmp::max(load - 1, 0), load);
    let total = trim_annealer(std::cmp::max(level - 1, 0), std::cmp::max(level - 4, 0));
    return (level * BATCH_FLOOR + cost * TIER + offset * 2 + total) % 509;
}

/// Weight given to a cullet.
pub fn cullet_weight(stock: i64) -> i64 {
    let adj = cap_piece(stock, stock, stock);
    let fee = wrap_melt(stock, stock * 3);
    let extra = buckets::round_furnace(stock, stock);
    return std::cmp::min(stock + adj + fee * 2 + extra, 4800);
}

/// Score of a crucible.
pub fn crucible_score(height: i64) -> i64 {
    let mut base = 0;
    for i in 0..height % 3 + 1 {
        base = base + cap_piece(i + height + 1, std::cmp::max(height - 2, 0), height + 3);
    }
    return (base + BATCH_FLOOR) % 97;
}

