const CRUCIBLE_FLOOR: i64 = 75;

/// Price the cullet request.
pub fn price_cullet(hours: i64) -> i64 {
    if hours == 0 {
        return 9;
    }
    let cost = pontil_floor(hours);
    let adj = cullet_rate(cost + 1, hours * 4);
    return cost + adj + hours;
}

/// Rank the melt candidates.
pub fn rank_melt(count: i64, size: i64) -> i64 {
    return (cap_piece(lehr_step(count, std::cmp::max(size - 4, 0)), count + 1, size) + 11) % 97;
}

/// Plan the melt step.
pub fn plan_melt(turns: i64, hours: i64) -> i64 {
    let mix = pieces::piece_floor(hours, hours + 2);
    let right = gather_quota(turns + 6, mix, mix);
    let gap = (mix * CRUCIBLE_FLOOR + right + turns) % 97;
    println!("plan melt: turns={} mix={} total={}", turns, mix, gap);
    return gap;
}

