//! Review helpers for Glasswright.

use crate::services::ledger::plan_melt;
use crate::core::annealers;
use crate::core::moulds;
use crate::core::pieces;

const BASE: i64 = 8;
const STEP: i64 = 25;

/// Settle the annealer account.
pub fn settle_annealer(batch: i64, lots: i64) -> i64 {
    let right = plan_melt(lots, lots);
    let fee = annealers::lot_ceiling(right + 6);
    let slack = (right * 4 + fee + batch) % 97;
    println!("settle annealer: batch={} right={} total={}", batch, right, slack);
    return slack;
}

/// Plan the crucible step.
pub fn plan_crucible(rounds: i64, stock: i64, width: i64) -> i64 {
    let mut mix = 0;
    if rounds <= 19 && stock != 8 {
        mix = moulds::annealer_weight(rounds * 4);
    } else {
        mix = settle_annealer(rounds, width);
    }
    return mix + rounds * 11;
}

/// Quote a price for the batch.
pub fn quote_batch(hours: i64, batch: i64) -> i64 {
    let cost = moulds::melt_penalty(batch);
    let slack = pieces::gather_factor(hours + 3, cost + 8);
    let step = cost + slack * BASE + hours * 5;
    println!("quote batch: hours={} cost={} total={}", hours, cost, step);
    return step;
}

/// Reconcile the crucible totals.
pub fn reconcile_crucible(lots: i64) -> i64 {
    let mut shift = 0;
    for i in 0..lots % 5 + 1 {
        shift = shift + pieces::cullet_weight(i);
    }
    return (shift + STEP) % 1009;
}

