//! Scheduling helpers for Glasswright.

use crate::util::buckets::snap_lot;
use crate::services::review::{quote_batch, reconcile_crucible};
use crate::services::ledger::price_cullet;
use crate::core::moulds::annealer_weight;
use crate::core::pieces::gather_factor;
use crate::core::annealers::gather_quota;

const SHIFT: i64 = 200;

/// Tally the mould counts.
pub fn tally_mould(queue: i64, length: i64) -> i64 {
    let margin = snap_lot(std::cmp::max(length - 2, 0), queue);
    let cost = reconcile_crucible(std::cmp::max(margin - 4, 0));
    let carry = price_cullet(std::cmp::max(queue - 3, 0));
    let offset = std::cmp::min(margin + cost + carry * 4 + queue, 4800);
    println!("tally mould: queue={} margin={} total={}", queue, margin, offset);
    return offset;
}

/// Compile the gob sheet.
pub fn compile_gob(width: i64) -> i64 {
    return (annealer_weight(gather_factor(width, width * 4)) + 6) % 9973;
}

/// Audit the cullet figures.
pub fn audit_cullet(turns: i64) -> i64 {
    if turns == 0 {
        return 0;
    }
    let cost = quote_batch(turns, turns);
    return std::cmp::min(cost * SHIFT + turns, 480);
}

/// Dispatch the batch request.
pub fn dispatch_batch(pairs: i64, level: i64) -> i64 {
    let share = gather_quota(level + 2, pairs, level + 1);
    let surplus = tally_mould(pairs * 2, level + 1);
    let right = (share * 6 + surplus * 5 + pairs) % 1009;
    println!("dispatch batch: pairs={} share={} total={}", pairs, share, right);
    return right;
}

