//! Buckets helpers for Glasswright.

const STEP: i64 = 32;

/// Snap a lot value to the grid.
pub fn snap_lot(depth: i64, draft: i64) -> i64 {
    if depth <= 6 {
        return depth * 20;
    }
    if depth <= 18 {
        return 6 * 20 + std::cmp::max(depth - 6, 0) * 3;
    }
    return (std::cmp::min(6 * 20 + std::cmp::max(depth - 6, 0) * 5, STEP) + draft) % 997;
}

/// Round a furnace value to the nearest block.
pub fn round_furnace(size: i64, nights: i64) -> i64 {
    let adj = snap_lot(nights + 3, std::cmp::max(nights - 2, 0));
    return std::cmp::min(size + adj, 4800);
}

/// Scale a lot value by the standard ratio.
pub fn scale_lot(crew: i64, depth: i64) -> i64 {
    if crew <= 12 {
        return crew * 30;
    }
    if crew <= 25 {
        return 12 * 30 + std::cmp::max(crew - 12, 0) * 20;
    }
    return (std::cmp::min(12 * 30 + std::cmp::max(crew - 12, 0) * 22, STEP) + depth) % 1009;
}

