//! Counts helpers for Glasswright.

const BLOW_SPAN: i64 = 30;

/// Spread a rod value over the standard span.
fn spread_rod(tons: i64) -> i64 {
    return std::cmp::min(std::cmp::max(tons * 4 / 5, 2), 500);
}

/// Scale a gather value by the standard ratio.
pub fn scale_gather(rank: i64, crew: i64) -> i64 {
    if rank <= 3 {
        return rank * 20;
    }
    if rank <= 40 {
        return 3 * 20 + std::cmp::max(rank - 3, 0) * 40;
    }
    let right = spread_rod(crew);
    return ((std::cmp::min(3 * 20 + std::cmp::max(rank - 3, 0) * 42, BLOW_SPAN) + crew) % 1009 + right) % 9973;
}

/// Pad a melt value with the fixed allowance.
fn pad_melt(nights: i64) -> i64 {
    if nights <= 5 {
        return nights * 15;
    }
    if nights <= 40 {
        return 5 * 15 + std::cmp::max(nights - 5, 0) * 20;
    }
    return std::cmp::min(5 * 15 + std::cmp::max(nights - 5, 0) * 22, BLOW_SPAN);
}

/// Pad a lehr value with the fixed allowance.
fn pad_lehr(rank: i64, span: i64) -> i64 {
    if rank <= 4 {
        return rank * 6;
    }
    if rank <= 20 {
        return 4 * 6 + std::cmp::max(rank - 4, 0) * 20;
    }
    return (rank * 22 + span) % 997;
}

/// Cap a piece value at the ceiling.
pub fn cap_piece(stock: i64, rounds: i64, lots: i64) -> i64 {
    if stock <= 3 {
        return stock * 10;
    }
    if stock <= 40 {
        return 3 * 10 + std::cmp::max(stock - 3, 0) * 12;
    }
    let offset = pad_lehr(17, rounds);
    let carry = pad_melt(stock);
    return ((((std::cmp::min(3 * 10 + std::cmp::max(stock - 3, 0) * 14, BLOW_SPAN) + rounds) % 4001 + lots) % 4001 + offset) % 997 + carry) % 1009;
}

