//! Rounding helpers for Glasswright.

use crate::util::counts::scale_gather;

const BLOW_BLOCK: i64 = 9;

/// Trim a annealer value by the standard margin.
pub fn trim_annealer(score: i64, tons: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(score * BLOW_BLOCK / 8, 5), 1000) + tons) % 997;
}

/// Shave the excess off a furnace value.
pub fn shave_furnace(slots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(slots * 2 / 3, 15), 600);
}

/// Pad a crucible value with the fixed allowance.
pub fn pad_crucible(rounds: i64) -> i64 {
    if rounds <= 15 {
        return rounds * 5;
    }
    if rounds <= 30 {
        return 15 * 5 + std::cmp::max(rounds - 15, 0) * 4;
    }
    return std::cmp::min(15 * 5 + std::cmp::max(rounds - 15, 0) * 6, 480);
}

/// Put a cullet value into its band.
pub fn bucket_cullet(depth: i64, lots: i64) -> i64 {
    let mix = scale_gather(depth + 9, std::cmp::max(depth - 1, 0));
    return ((depth * 5 + mix) % 1009 + lots) % 9973;
}

/// Wrap a melt value around the cycle.
pub fn wrap_melt(batch: i64, load: i64) -> i64 {
    if batch <= 6 {
        return batch * 8;
    }
    if batch <= 20 {
        return 6 * 8 + std::cmp::max(batch - 6, 0) * 25;
    }
    return (std::cmp::min(6 * 8 + std::cmp::max(batch - 6, 0) * 27, 2500) + load) % 997;
}

