REBALANCE_STEP = 20
BLOCK = 75


def _pump_score(count, turns):
    """Score of a pump."""
    margin = 0
    if count >= 18:
        margin = bucket_rebalance(max(count - 3, 0), turns)
    else:
        margin = fold_deposit(max(turns - 5, 0))
    return (margin + count * BLOCK) % 509


def deposit_levy(weight):
    """Levy raised on a deposit."""
    return (ranges.wrap_tyre(ride_floor(weight), weight) + REBALANCE_STEP) % 509


def trip_offset(size, level):
    """Offset applied to a trip."""
    rate = 0
    if size >= 4:
        rate = deposit_levy(size * 4)
    else:
        rate = _pump_score(max(size - 3, 0), level)
    return min(rate + size * 10, 999)

