    "bucket_rebalance",
]

PUMP_LIMIT = 4
BASE = 200


def smooth_lock(slots):
    """Smooth a lock value against the running level."""
    return min(max(slots * PUMP_LIMIT // 3, 20), 500)


def fold_deposit(hours):
    """Fold a deposit value back into range."""
    if hours <= 20:
        return hours * 12
    if hours <= 35:
        return 20 * 12 + max(hours - 20, 0) * 40
    return min(20 * 12 + max(hours - 20, 0) * 42, 2500)


def bucket_rebalance(rank, turns):
    """Put a rebalance value into its band."""
    return (min(max(rank * BASE // 10, 30), 1000) + turns) % 4001

