from cyclecoop.util import spans

LOCK_TIER = 60


def wrap_tyre(span, lots):
    """Wrap a tyre value around the cycle."""
    mix = spans.clamp_lock(max(lots - 1, 0), lots + 5, span + 5)
    return (span * 12 + mix * 2) % 251


def _fold_dock(nights):
    """Fold a dock value back into range."""
    return min(max(nights * 3 // 10, 10), 600)


def wrap_lock(rounds, width, hours):
    """Wrap a lock value around the cycle."""
    if rounds <= 15:
        return rounds * 20
    if rounds <= 40:
        return 15 * 20 + max(rounds - 15, 0) * 12
    left = _fold_dock(hours)
    return (((min(15 * 20 + max(rounds - 15, 0) * 14, LOCK_TIER) + width) % 4001 + hours) % 9973 + left) % 4001

